"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[23],{6239:(a,e,n)=>{n.d(e,{b:()=>i});let i=[{id:"pura-tanah-lot",name:"Pura Tanah Lot",region:"Tabanan, Bali",areaLabel:{en:"Sacred coastal temple area",id:"Kawasan pura tepi laut"},description:{en:"A temple set on a rocky outcrop along the coast of Tabanan, surrounded by crashing waves and known for its sunset views across the Indian Ocean.",id:"Pura yang berdiri di atas batu karang di pesisir Tabanan, dikelilingi deburan ombak dan dikenal dengan pemandangan matahari terbenam di Samudra Hindia."},lat:-8.6212,lng:115.0868,radiusM:400,image:"/sites/pura-tanah-lot.jpg",source:"Bali Governor Circular No. 7/2025",background:{text:{en:"A sea temple associated with the 16th-century priest Dang Hyang Nirartha, and one of the seven sea temples ringing Bali's south-west coast. It honours Baruna, the god of the sea. More than a third of the rock it stands on is artificial, rebuilt in the 1980s to stop the outcrop crumbling into the water.",id:"Pura laut yang dikaitkan dengan pendeta abad ke-16 Dang Hyang Nirartha, dan satu dari tujuh pura laut yang mengelilingi pesisir barat daya Bali. Pura ini memuja Baruna, dewa laut. Lebih dari sepertiga batu karang tempatnya berdiri adalah buatan, dibangun ulang pada 1980-an agar karang itu tidak runtuh ke laut."},source:"Wikipedia: Tanah Lot",sourceUrl:"https://en.wikipedia.org/wiki/Tanah_Lot"},odalan:[{date:"2027-01-27",anchor:{en:"Buda Wage Langkir, every 210 days",id:"Buda Wage Langkir, tiap 210 hari"},source:"tanahlot.id, the temple's own site, gives the pujawali as Buda Cemeng Langkir. Counted 210 days on from the 1 July 2026 pujawali. The weekday checks out: Buda is Wednesday, and 27 January 2027 is a Wednesday.",sourceUrl:"https://www.tanahlot.id/article/pujawali-di-pura-luhur-tanah-lot-"}],customs:[{id:"dress",icon:"dress",title:{en:"Dress",id:"Pakaian"},summary:{en:"A kamen and sash are required to enter the grounds.",id:"Kamen dan selendang wajib dipakai untuk masuk ke area pura."},detail:{en:"Wear a kamen, a length of cloth wrapped at the waist, with a sash tied over it. Both are lent or rented at the entrance. Shoulders and knees stay covered inside the grounds.",id:"Kenakan kamen, kain yang dililitkan di pinggang, dengan selendang diikat di atasnya. Keduanya dipinjamkan atau disewakan di pintu masuk. Bahu dan lutut tetap tertutup selama di dalam area pura."},ruleIds:["temple-attire"]},{id:"photography",icon:"photography",title:{en:"Photography",id:"Fotografi"},summary:{en:"Photos are fine outside the inner courtyard.",id:"Foto diperbolehkan di luar halaman dalam."},detail:{en:"Take photos in the outer areas. Ask before photographing someone who is praying, and never stand higher than a priest to get a shot.",id:"Ambil foto di area luar. Minta izin sebelum memotret orang yang sedang sembahyang, dan jangan pernah berdiri lebih tinggi daripada pedanda untuk mengambil gambar."},ruleIds:["photography","head-level-respect"]},{id:"offerings",icon:"offerings",title:{en:"Offerings",id:"Sesaji"},summary:{en:"Canang are placed on the ground. Walk around them.",id:"Canang diletakkan di tanah. Berjalanlah mengelilinginya."},detail:{en:"Canang, small woven trays of flowers, are placed on the ground throughout the area. Walk around them, never over them or on them.",id:"Canang, wadah anyaman kecil berisi bunga, diletakkan di tanah di seluruh area. Berjalanlah mengelilinginya, jangan pernah melangkahinya atau menginjaknya."},ruleIds:["offerings-canang"]},{id:"drones",icon:"drones",title:{en:"Drones",id:"Drone"},summary:{en:"Flying over the temple area is not permitted.",id:"Menerbangkan drone di area pura tidak diizinkan."},detail:{en:"Flying over the temple area is not permitted. This is enforced, and it interrupts ceremonies.",id:"Menerbangkan drone di area pura tidak diizinkan. Hal ini ditegakkan dan dapat mengganggu upacara."},ruleIds:["drone-restriction"]},{id:"quiet",icon:"quiet",title:{en:"Quiet",id:"Tenang"},summary:{en:"Keep your voice low near people who are praying.",id:"Jaga suara tetap pelan di dekat orang yang sedang sembahyang."},detail:{en:"Keep your voice low near people who are praying, and let a ceremony pass rather than crossing through it.",id:"Jaga suara tetap pelan di dekat orang yang sedang sembahyang, dan biarkan upacara berlalu alih-alih menyeberang di tengahnya."},ruleIds:["speaking-volume"]}]},{id:"pura-luhur-uluwatu",name:"Pura Luhur Uluwatu",region:"Badung, Bali",areaLabel:{en:"Clifftop sacred area",id:"Kawasan suci di atas tebing"},description:{en:"A cliff-edge temple on the southern tip of Bali, overlooking the Indian Ocean. A kecak dance stage stands on the clifftop beside it.",id:"Pura di tepi tebing ujung selatan Bali, menghadap Samudra Hindia. Sebuah panggung tari kecak berdiri di atas tebing di sampingnya."},lat:-8.8291,lng:115.0849,radiusM:400,image:"/sites/pura-luhur-uluwatu.jpg",source:"Bali Governor Circular No. 7/2025",background:{text:{en:"Expanded in the 11th century by the Javanese sage Empu Kuturan, and added to by Dang Hyang Nirartha in the 16th. It is dedicated to Sang Hyang Widhi Wasa in the form of Rudra, and it is the only Balinese sea temple that is also one of the island's directional temples.",id:"Diperluas pada abad ke-11 oleh pendeta Jawa Empu Kuturan, lalu dilengkapi Dang Hyang Nirartha pada abad ke-16. Pura ini dipersembahkan kepada Sang Hyang Widhi Wasa dalam wujud Rudra, dan satu-satunya pura laut di Bali yang sekaligus menjadi pura penjaga arah mata angin."},source:"Wikipedia: Uluwatu Temple",sourceUrl:"https://en.wikipedia.org/wiki/Uluwatu_Temple"},odalan:[{date:"2027-02-02",anchor:{en:"Anggara Kasih Medangsia, every 210 days",id:"Anggara Kasih Medangsia, tiap 210 hari"},source:"Bali Post reported the pujawali on 9 December 2025, which is 210 days after the 13 May 2025 one recorded by the Kuta Selatan district office. Two more cycles on lands 2 February 2027, and the weekday checks out: Anggara is Tuesday, and 2 February 2027 is a Tuesday.",sourceUrl:"https://www.balipost.com/news/2025/12/05/510827/Pujawali-Pura-Uluwatu-9-Desember,Diawali...html"}],customs:[{id:"dress",icon:"dress",title:{en:"Dress",id:"Pakaian"},summary:{en:"A kamen and sash are required inside the temple.",id:"Kamen dan selendang wajib dikenakan di dalam pura."},detail:{en:"A kamen and sash are required inside the temple grounds. They are lent or rented at the entrance. Keep shoulders and knees covered.",id:"Kamen dan selendang wajib dikenakan di dalam area pura. Keduanya dipinjamkan atau disewakan di pintu masuk. Jaga bahu dan lutut tetap tertutup."},ruleIds:["temple-attire"]},{id:"photography",icon:"photography",title:{en:"Photography",id:"Fotografi"},summary:{en:"Photos are fine on the clifftop path.",id:"Foto diperbolehkan di jalan setapak tebing."},detail:{en:"Photograph the cliff views and the outer areas freely. Ask before photographing someone who is praying, and avoid taking photos inside the inner courtyard.",id:"Foto pemandangan tebing dan area luar dengan leluasa. Minta izin sebelum memotret orang yang sedang sembahyang, dan hindari memotret di halaman dalam."},ruleIds:["photography","sacred-area-entry"]},{id:"offerings",icon:"offerings",title:{en:"Offerings",id:"Sesaji"},summary:{en:"Offerings rest on the ground and on walls.",id:"Sesaji diletakkan di tanah dan di tembok."},detail:{en:"Offerings are placed on the ground and along the temple walls. Step around them and never walk over them.",id:"Sesaji diletakkan di tanah dan di sepanjang tembok pura. Berjalanlah mengelilinginya dan jangan pernah melangkahinya."},ruleIds:["offerings-canang"]},{id:"quiet",icon:"quiet",title:{en:"Quiet",id:"Tenang"},summary:{en:"Stay quiet near the shrines and the kecak stage.",id:"Tetap tenang di dekat pelinggih dan panggung kecak."},detail:{en:"Stay quiet near the shrines and the kecak dance stage. Let a ceremony pass rather than crossing through it, and keep your voice low.",id:"Tetap tenang di dekat pelinggih dan panggung tari kecak. Biarkan upacara berlalu alih-alih menyeberang di tengahnya, dan jaga suara tetap pelan."},ruleIds:["speaking-volume"]}]},{id:"pura-besakih",name:"Pura Besakih",region:"Karangasem, Bali",areaLabel:{en:"Mother temple complex",id:"Kompleks pura agung"},description:{en:"The largest and most important temple complex in Bali, spanning the slopes of Mount Agung. It consists of over twenty separate temples.",id:"Kompleks pura terbesar dan terpenting di Bali, membentang di lereng Gunung Agung. Kompleks ini terdiri dari lebih dari dua puluh pura terpisah."},lat:-8.3739,lng:115.4515,radiusM:500,image:"/sites/pura-besakih.jpg",source:"Bali Governor Circular No. 7/2025",background:{text:{en:"The largest and holiest temple of Balinese Hinduism: twenty-three temples on the slope of Mount Agung. Hindu use is documented from 1284, and stone terraces on the site resemble megalithic work far older than that. Its principal sanctuary is Pura Penataran Agung, which the whole terraced complex faces.",id:"Pura terbesar dan tersuci dalam Hindu Bali: dua puluh tiga pura di lereng Gunung Agung. Penggunaannya sebagai pura Hindu tercatat sejak 1284, dan teras batu di situs ini menyerupai bangunan megalitik yang jauh lebih tua. Pura utamanya adalah Pura Penataran Agung, yang dihadapi seluruh kompleks berteras ini."},source:"Wikipedia: Besakih Temple",sourceUrl:"https://en.wikipedia.org/wiki/Besakih_Temple"},odalan:[],customs:[{id:"dress",icon:"dress",title:{en:"Dress",id:"Pakaian"},summary:{en:"A kamen and sash are required across the complex.",id:"Kamen dan selendang wajib dikenakan di seluruh kompleks."},detail:{en:"A kamen and sash are required across the whole complex, the largest temple in Bali. They are lent or rented at the main entrance.",id:"Kamen dan selendang wajib dikenakan di seluruh kompleks, pura terbesar di Bali. Keduanya dipinjamkan atau disewakan di pintu masuk utama."},ruleIds:["temple-attire"]},{id:"photography",icon:"photography",title:{en:"Photography",id:"Fotografi"},summary:{en:"Photos are fine in the outer courtyards.",id:"Foto diperbolehkan di halaman luar."},detail:{en:"Photograph the outer courtyards and the meru shrines. Ask before photographing someone who is praying, and never stand higher than a priest.",id:"Foto halaman luar dan pelinggih meru. Minta izin sebelum memotret orang yang sedang sembahyang, dan jangan pernah berdiri lebih tinggi daripada pedanda."},ruleIds:["photography","head-level-respect"]},{id:"offerings",icon:"offerings",title:{en:"Offerings",id:"Sesaji"},summary:{en:"Offerings cover the ground during ceremonies.",id:"Sesaji memenuhi tanah saat upacara."},detail:{en:"Offerings are laid out widely, especially on ceremony days. Walk around them and never step on them, even if the ground looks busy.",id:"Sesaji diletakkan secara luas, terutama pada hari upacara. Berjalanlah mengelilinginya dan jangan pernah menginjaknya, meskipun tanah tampak ramai."},ruleIds:["offerings-canang"]},{id:"drones",icon:"drones",title:{en:"Drones",id:"Drone"},summary:{en:"Flying drones over the complex is not permitted.",id:"Menerbangkan drone di atas kompleks tidak diizinkan."},detail:{en:"Flying drones over the temple complex is not permitted. This is enforced, and it interrupts ceremonies.",id:"Menerbangkan drone di atas kompleks pura tidak diizinkan. Hal ini ditegakkan dan dapat mengganggu upacara."},ruleIds:["drone-restriction"]},{id:"quiet",icon:"quiet",title:{en:"Quiet",id:"Tenang"},summary:{en:"Keep your voice low in the courtyards.",id:"Jaga suara tetap pelan di halaman."},detail:{en:"Keep your voice low across the courtyards. Many people come here to pray, and ceremonies are frequent. Let them pass without crossing through.",id:"Jaga suara tetap pelan di seluruh halaman. Banyak orang datang untuk sembahyang, dan upacara sering berlangsung. Biarkan mereka berlalu tanpa menyeberang di tengahnya."},ruleIds:["speaking-volume"]}]},{id:"pura-batu-bolong",name:"Pura Batu Bolong",region:"Badung, Bali",areaLabel:{en:"Temple on the rock arch",id:"Pura di atas lengkung batu"},description:{en:"A small temple built on a natural rock arch that juts into the sea near Canggu. It sits beside Tanah Lot and shares the same coastline.",id:"Pura kecil yang dibangun di atas lengkung batu alami yang menjorok ke laut dekat Canggu. Letaknya berdampingan dengan Tanah Lot di garis pantai yang sama."},lat:-8.6547,lng:115.1225,radiusM:250,image:"/sites/pura-batu-bolong.jpg",source:"Bali Governor Circular No. 7/2025",background:{text:{en:"Tradition ties this temple to Dang Hyang Nirartha's journey through Bali in 1489, and to seven freshwater springs said to have risen in the sea along that route. Four of them are held to lie in front of this temple. It is a place of worship for Ida Batara Segara, who rules the sea.",id:"Tradisi mengaitkan pura ini dengan perjalanan Dang Hyang Nirartha di Bali pada 1489, dan dengan tujuh mata air tawar yang diyakini muncul di laut sepanjang jalur itu. Empat di antaranya diyakini berada di depan pura ini. Pura ini menjadi tempat pemujaan Ida Batara Segara, penguasa laut."},source:"Bali Express, Jawa Pos",sourceUrl:"https://baliexpress.jawapos.com/balinese/2502240010/pura-batu-bolong-canggu-diyakini-petilasan-dang-hyang-nirartha-ada-mata-air-tawar-di-tengah-laut"},odalan:[],customs:[{id:"dress",icon:"dress",title:{en:"Dress",id:"Pakaian"},summary:{en:"A kamen is required to cross the rock arch.",id:"Kamen wajib dikenakan untuk melewati lengkung batu."},detail:{en:"A kamen is required to enter the temple over the rock arch. It is lent or rented at the entrance. Keep shoulders and knees covered.",id:"Kamen wajib dikenakan untuk masuk ke pura di atas lengkung batu. Kamen dipinjamkan atau disewakan di pintu masuk. Jaga bahu dan lutut tetap tertutup."},ruleIds:["temple-attire"]},{id:"offerings",icon:"offerings",title:{en:"Offerings",id:"Sesaji"},summary:{en:"Offerings are placed along the cliff edge.",id:"Sesaji diletakkan di sepanjang tepi tebing."},detail:{en:"Offerings are placed along the cliff edge and at the shrines. Walk around them and never kick or step on them.",id:"Sesaji diletakkan di sepanjang tepi tebing dan di pelinggih. Berjalanlah mengelilinginya dan jangan pernah menyentuh atau menginjaknya."},ruleIds:["offerings-canang"]},{id:"quiet",icon:"quiet",title:{en:"Quiet",id:"Tenang"},summary:{en:"Keep your voice low near the shrines.",id:"Jaga suara tetap pelan di dekat pelinggih."},detail:{en:"Keep your voice low near the shrines and let a ceremony pass rather than crossing through it.",id:"Jaga suara tetap pelan di dekat pelinggih dan biarkan upacara berlalu alih-alih menyeberang di tengahnya."},ruleIds:["speaking-volume"]}]},{id:"pura-tirta-empul",name:"Pura Tirta Empul",region:"Gianyar, Bali",areaLabel:{en:"Sacred spring purification temple",id:"Pura pemandian air suci"},description:{en:"A water temple in Tampaksiring fed by a natural spring. Visitors come to bathe in its pools as part of the melukat purification ritual.",id:"Pura air di Tampaksiring yang dialiri mata air alami. Pengunjung datang untuk mandi di kolamnya sebagai bagian dari ritual penyucian melukat."},lat:-8.4156,lng:115.3153,radiusM:300,image:"/sites/pura-tirta-empul.jpg",source:"Bali Governor Circular No. 7/2025",background:{text:{en:"Founded around 962, under the Warmadewa dynasty, around a spring that rises out of the ground. The name means the holy spring that wells up. Its pools are used for melukat, the rite of purification, and the bathing spouts stand in the middle of three courtyards.",id:"Didirikan sekitar tahun 962, pada masa dinasti Warmadewa, mengelilingi mata air yang menyembur dari tanah. Namanya berarti mata air suci yang muncul dari bumi. Kolamnya dipakai untuk melukat, ritual penyucian, dan pancurannya berdiri di tengah tiga halaman pura."},source:"Wikipedia: Tirta Empul",sourceUrl:"https://en.wikipedia.org/wiki/Tirta_Empul"},odalan:[{date:"2026-09-28",anchor:{en:"Purnama Kapat, once a year",id:"Purnama Kapat, setahun sekali"},source:"Gianyar regency government, announcing the Karya Padudusan Agung. The series runs 26 to 29 September 2026, with Purnama Kapat on the 28th and the piodalan peak on the 29th.",sourceUrl:"https://gianyarkab.go.id/informasi-publik/berita/karya-padudusan-agung-di-pura-tirta-empul-tampaksiring"}],customs:[{id:"dress",icon:"dress",title:{en:"Dress",id:"Pakaian"},summary:{en:"A kamen is required before the bathing pools.",id:"Kamen wajib dikenakan sebelum masuk area pemandian."},detail:{en:"A kamen is required to reach the bathing pools, and is lent or rented at the entrance. Keep your shoulders covered.",id:"Kamen wajib dikenakan untuk mencapai kolam pemandian, dan dipinjamkan atau disewakan di pintu masuk. Jaga bahu tetap tertutup."},ruleIds:["temple-attire"]},{id:"photography",icon:"photography",title:{en:"Photography",id:"Fotografi"},summary:{en:"Photos are fine from the poolside paths.",id:"Foto diperbolehkan dari jalur tepi kolam."},detail:{en:"Photograph the pools from the surrounding paths. Ask before photographing someone who is purifying, and do not stand higher than a priest.",id:"Foto kolam dari jalur di sekelilingnya. Minta izin sebelum memotret orang yang sedang melukat, dan jangan berdiri lebih tinggi daripada pedanda."},ruleIds:["photography","head-level-respect"]},{id:"offerings",icon:"offerings",title:{en:"Offerings",id:"Sesaji"},summary:{en:"Offerings line the pools and walkways.",id:"Sesaji berjajar di kolam dan jalur."},detail:{en:"Offerings are placed around the pools and along the walkways. Step around them and never walk over them.",id:"Sesaji diletakkan di sekitar kolam dan di sepanjang jalur. Berjalanlah mengelilinginya dan jangan pernah melangkahinya."},ruleIds:["offerings-canang"]},{id:"quiet",icon:"quiet",title:{en:"Quiet",id:"Tenang"},summary:{en:"Keep your voice low near the water.",id:"Jaga suara tetap pelan di dekat air."},detail:{en:"People come here to purify in silence. Keep your voice low and let those who are bathing finish without disturbance.",id:"Orang datang ke sini untuk melukat dengan hening. Jaga suara tetap pelan dan biarkan mereka yang sedang mandi selesai tanpa gangguan."},ruleIds:["speaking-volume"]}]},{id:"pura-ulun-danu-beratan",name:"Pura Ulun Danu Beratan",region:"Tabanan, Bali",areaLabel:{en:"Temple on the mountain lake",id:"Pura di tepi danau pegunungan"},description:{en:"A lakeside temple on the shore of Lake Beratan in the central highlands. Its multi-tiered meru shrines appear to float when the water is high.",id:"Pura di tepi Danau Beratan di dataran tinggi tengah Bali. Pelinggih meru bertingkatnya tampak mengapung saat air danau sedang tinggi."},lat:-8.275,lng:115.1668,radiusM:350,image:"/sites/Pura_Ulun_Batu_Beratan.jpg",source:"Bali Governor Circular No. 7/2025",background:{text:{en:"Built in 1633 on the shore of Lake Beratan and dedicated to Dewi Danu, goddess of water, lakes and rivers. The lake feeds the subak irrigation of central Bali, and the smaller water temples downstream belong to individual subak associations. Its eleven-tiered meru is dedicated to Shiva and Parvati.",id:"Dibangun pada 1633 di tepi Danau Beratan dan dipersembahkan kepada Dewi Danu, dewi air, danau, dan sungai. Danau ini mengairi subak di Bali tengah, dan pura-pura air yang lebih kecil di hilirnya milik masing-masing perkumpulan subak. Meru bertingkat sebelasnya dipersembahkan kepada Siwa dan Parwati."},source:"Wikipedia: Pura Ulun Danu Bratan",sourceUrl:"https://en.wikipedia.org/wiki/Pura_Ulun_Danu_Bratan"},odalan:[],customs:[{id:"dress",icon:"dress",title:{en:"Dress",id:"Pakaian"},summary:{en:"A kamen and sash are required inside the temple.",id:"Kamen dan selendang wajib dikenakan di dalam pura."},detail:{en:"A kamen and sash are required inside the temple grounds on the lake. They are lent or rented at the entrance.",id:"Kamen dan selendang wajib dikenakan di dalam area pura di tepi danau. Keduanya dipinjamkan atau disewakan di pintu masuk."},ruleIds:["temple-attire"]},{id:"photography",icon:"photography",title:{en:"Photography",id:"Fotografi"},summary:{en:"Photos are fine around the lake gardens.",id:"Foto diperbolehkan di sekitar taman danau."},detail:{en:"Photograph the lake and the surrounding gardens freely. Ask before photographing someone who is praying, and keep to the paths.",id:"Foto danau dan taman di sekelilingnya dengan leluasa. Minta izin sebelum memotret orang yang sedang sembahyang, dan tetap di jalur."},ruleIds:["photography"]},{id:"drones",icon:"drones",title:{en:"Drones",id:"Drone"},summary:{en:"Flying drones over the lake is not permitted.",id:"Menerbangkan drone di atas danau tidak diizinkan."},detail:{en:"Flying drones over the temple or the lake is not permitted. This is enforced, and it disturbs the calm of the site.",id:"Menerbangkan drone di atas pura atau danau tidak diizinkan. Hal ini ditegakkan dan mengganggu ketenangan kawasan."},ruleIds:["drone-restriction"]},{id:"quiet",icon:"quiet",title:{en:"Quiet",id:"Tenang"},summary:{en:"Keep your voice low near the lake shrine.",id:"Jaga suara tetap pelan di dekat pelinggih danau."},detail:{en:"Keep your voice low near the shrine and the gardens. Let a ceremony pass rather than crossing through it.",id:"Jaga suara tetap pelan di dekat pelinggih dan taman. Biarkan upacara berlalu alih-alih menyeberang di tengahnya."},ruleIds:["speaking-volume"]}]}]},9201:(a,e,n)=>{n.d(e,{A:()=>i});let i=(0,n(4294).A)("ShieldCheck",[["path",{d:"M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z",key:"oel41y"}],["path",{d:"m9 12 2 2 4-4",key:"dzmm74"}]])}}]);